 /** Message keys per language, for checks. */
 export const messageKeys = (lang) => Object.keys(MESSAGES[lang] ?? {});
+
+/** The language to answer in: the best `Accept-Language` match (q-values, region tags), else `fallback`. */
+export function pickLanguage(header, fallback = LANGUAGES[0]) {
+  if (typeof header !== "string" || !header.trim()) return fallback;
+  const wanted = [];
+  header.split(",").forEach((part, i) => {
+    const [range, ...attrs] = part.trim().split(";").map((s) => s.trim());
+    if (!range) return;
+    let q = 1;
+    for (const a of attrs) {
+      const m = /^q\s*=\s*([0-9.]+)$/i.exec(a);
+      if (m) q = /^(0(\.\d{0,3})?|1(\.0{0,3})?)$/.test(m[1]) ? Number(m[1]) : 0;
+    }
+    if (q <= 0) return;
+    const primary = range.toLowerCase().split("-")[0];
+    const lang = primary === "*" ? fallback : primary;
+    if (LANGUAGES.includes(lang)) wanted.push({ lang, q, i });
+  });
+  wanted.sort((a, b) => b.q - a.q || a.i - b.i);
+  return wanted.length ? wanted[0].lang : fallback;
+}
